<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import type {Api} from './api'
interface Account {id:string;username:string;enabled:boolean;version:number;talent_id:string|null;talent_name:string|null;department_id:string|null;role_ids:string[]}
const props=defineProps<{api:Api;departments:{id:string;name?:string;enabled:boolean}[]}>()
const items=ref<Account[]>([]),roles=ref<{id:string;name:string}[]>([]),total=ref(0),page=ref(1),busy=ref(false),editing=ref<Account|null>(null),creating=ref(false)
const choices=ref<{id:string;name:string;kind:string}[]>([]),form=ref({username:'',password:'',department_id:null as string|null})
async function run(fn:()=>Promise<void>){busy.value=true;try{await fn()}catch(e){ElMessage.error((e as Error).message)}finally{busy.value=false}}
async function load(){const data=await props.api<{items:Account[];total:number}>(`/admin/user-page?offset=${(page.value-1)*20}&limit=20`);items.value=data.items;total.value=data.total;roles.value=await props.api('/admin/roles')}
let searchSerial=0
async function search(query:string){const ticket=++searchSerial;try{const data=await props.api<{items:typeof choices.value}>(`/admin/binding-choices?q=${encodeURIComponent(query)}&limit=100`);if(ticket===searchSerial)choices.value=data.items}catch(e){if(ticket===searchSerial)ElMessage.error((e as Error).message)}}
function edit(account:Account){editing.value=JSON.parse(JSON.stringify(account));choices.value=account.talent_id?[{id:account.talent_id,name:account.talent_name||'当前绑定人才',kind:''}]:[]}
async function save(){if(editing.value&&!editing.value.enabled&&items.value.find(a=>a.id===editing.value?.id)?.enabled){try{await ElMessageBox.confirm('停用后该账号不能继续访问，已有业务记录保留。','停用账号',{confirmButtonText:'确认停用并保存',cancelButtonText:'取消',type:'warning'})}catch{return}}await run(async()=>{const a=editing.value!;await props.api(`/admin/users/${a.id}`,'PATCH',{version:a.version,enabled:a.enabled,role_ids:a.role_ids,talent_id:a.talent_id||null,department_id:a.department_id});editing.value=null;await load();ElMessage.success('账号授权已保存')})}
async function create(){await run(async()=>{await props.api('/admin/users','POST',form.value);form.value={username:'',password:'',department_id:null};creating.value=false;await load();ElMessage.success('账号已创建，请配置角色与人才绑定')})}
onMounted(()=>run(load))
</script>
<template>
  <div class="title-row"><h1>账号管理</h1><el-button type="primary" @click="creating=true">新建账号</el-button></div>
  <p class="muted">账号角色决定功能与数据范围，人才绑定用于识别员工本人；管理员身份不自动获得人才正文权限。</p>
  <el-card v-loading="busy"><el-table :data="items"><el-table-column prop="username" label="账号" min-width="130"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'">{{row.enabled?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="角色" min-width="180"><template #default="{row}"><div class="tag-list"><el-tag v-for="id in row.role_ids" :key="id" size="small">{{roles.find(r=>r.id===id)?.name||'未找到角色'}}</el-tag><span v-if="!row.role_ids.length" class="muted">未配置角色</span></div></template></el-table-column><el-table-column label="部门" min-width="120"><template #default="{row}">{{departments.find(d=>d.id===row.department_id)?.name||'未设置'}}</template></el-table-column><el-table-column prop="talent_name" label="绑定人才" min-width="140"><template #default="{row}">{{row.talent_name||'未绑定'}}</template></el-table-column><el-table-column label="操作" width="100"><template #default="{row}"><el-button link type="primary" @click="edit(row)">编辑账号</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="run(load)"/></el-card>
  <el-dialog v-model="creating" title="新建账号" width="min(520px,94vw)" :close-on-click-modal="false"><el-form label-position="top" @submit.prevent="create"><el-form-item label="账号" required><el-input v-model="form.username" autocomplete="off"/></el-form-item><el-form-item label="部门"><el-select v-model="form.department_id" clearable><el-option v-for="d in departments.filter(d=>d.enabled)" :key="d.id" :value="d.id" :label="d.name"/></el-select></el-form-item><el-form-item label="初始密码（至少 12 字符）" required><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item></el-form><template #footer><el-button @click="creating=false;form.password=''">取消</el-button><el-button type="primary" :loading="busy" @click="create">创建账号</el-button></template></el-dialog>
  <el-dialog :model-value="!!editing" title="编辑账号" width="min(560px,94vw)" :close-on-click-modal="false" @close="editing=null"><el-form v-if="editing" label-position="top"><el-form-item label="账号"><strong>{{editing.username}}</strong></el-form-item><el-form-item label="状态"><el-switch v-model="editing.enabled" active-text="启用" inactive-text="停用"/></el-form-item><el-form-item label="角色"><el-select v-model="editing.role_ids" multiple><el-option v-for="r in roles" :key="r.id" :value="r.id" :label="r.name"/></el-select></el-form-item><el-form-item label="账号部门"><el-select v-model="editing.department_id" clearable><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name" :disabled="!d.enabled&&d.id!==editing.department_id"/></el-select></el-form-item><el-form-item label="人才绑定"><el-select v-model="editing.talent_id" remote filterable clearable :remote-method="search" placeholder="输入姓名搜索人才"><el-option v-for="t in choices" :key="t.id" :value="t.id" :label="`${t.name}${t.kind?' · '+(t.kind==='internal'?'内部员工':'外部候选人'):''}`"/></el-select></el-form-item><p class="muted">保存后下次请求即使用新权限；停用账号将阻止其继续访问。</p></el-form><template #footer><el-button @click="editing=null">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存账号</el-button></template></el-dialog>
</template>
